<script setup lang="ts">
import DateField from './DateField.vue';
import {ref,computed,onMounted} from 'vue';import {useRoute} from 'vue-router';import {post,safeOfficialUrl} from '../api/client';import {indicator,time} from '../presentation/zh';
const props=defineProps<{token:string}>();const transmissionAvailable=location.port==='5180';type Row=Record<string,any>;const route=useRoute();const catalog=ref<Row[]>([]),overview=ref<Row>({}),data=ref<Row>({}),series=ref(String(route.query.series||'')),page=ref(0),from=ref(String(route.query.from||'')),to=ref(String(route.query.to||'')),rangeStart=ref(''),asOf=ref(''),error=ref(''),busy=ref(false);
const labels:Record<string,string>={previous:'上一有效观测期',mom:'月度环比',qoq:'季度环比',yoy:'年度同比',range:'同频率历史区间'};
const rows=computed<Row[]>(()=>data.value.observations||[]);const actual=computed(()=>rows.value.filter(r=>r.metadata&&r.original_value!=null).slice().reverse());const points=computed(()=>{const values=actual.value.map(r=>Number(r.original_value));const min=Math.min(...values),max=Math.max(...values);return values.map((v,i)=>`${30+i*740/Math.max(values.length-1,1)},${180-(v-min)*150/(max-min||1)}`).join(' ')});
const unit=computed(()=>{const m=rows.value[0]?.metadata;return m?.CURRENCY_DENOM?`${m.UNIT} / ${m.CURRENCY_DENOM}（每1单位分母货币）`:m?.UNIT==='PCPA'?'年化百分比（PCPA）':m?.UNIT||'单位待核验'});
const display=(v:any)=>v==null?'暂无可比数据':v;async function load(){busy.value=true;error.value='';try{data.value=await post('/macro-changes/detail',props.token,{series:series.value,page:page.value,from:from.value||null,to:to.value||null,rangeStart:rangeStart.value||null,asOf:asOf.value?new Date(asOf.value+'+08:00').toISOString():null});}catch(e){error.value=(e as Error).message}finally{busy.value=false;}}
onMounted(async()=>{try{[catalog.value,overview.value]=await Promise.all([post<Row[]>('/macro-changes/catalog',props.token,{page:0}),post<Row>('/macro-changes/overview',props.token)]);if(!series.value)series.value=catalog.value[0]?.id||'';if(series.value)await load();}catch(e){error.value=(e as Error).message}});
</script>
<template><section class="macro-change"><h2>全球官方宏观变化分析</h2><p>官方事实、数学计算、研究解释分别展示。参考汇率不等同实时成交行情。</p><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">正在核验原始观测与计算依据…</p><div class="overview"><span>官方来源 {{overview.official_sources??'—'}}</span><span>已核验指标序列 {{overview.verified_series??'—'}}</span><span>实际观测 {{overview.observations??'—'}}</span><span>存在可比变化 {{overview.comparable_series??'—'}}（最近100期）</span><span>待核验观测 {{overview.pending_data??'—'}}</span><span>来源异常 {{overview.source_anomalies??'—'}}</span></div><h3>指标目录</h3><details><summary>查看全部指标定义与数据库最新观测</summary><article v-for="s in catalog" :key="s.id"><b>{{indicator(s.id)||'中文名称待核验'}}</b><p>{{s.title}} · {{s.region}} · {{s.publisher}} · 原始频率 {{s.frequency}} · 原始单位 {{s.units}} · 单位分母 {{s.currency_denominator||'不适用'}}</p><p>最新观测期 {{s.latest_period||'未取得'}} · 最新原始值 {{s.latest_value??'未取得'}} · 元数据更新 {{time(s.updated_at)}}</p><p>指标代码 {{s.id}}；详细计算先核验原始CSV。</p></article></details><div class="filters"><label>官方指标<select v-model="series" @change="page=0;load()"><option v-for="s in catalog" :key="s.id" :value="s.id">{{indicator(s.id)||'中文名称待核验'}} · {{s.id}}</option></select></label><label>观测起日<DateField v-model="from" aria-label="观测起日"/></label><label>观测止日<DateField v-model="to" aria-label="观测止日"/></label><label>区间比较起日<DateField v-model="rangeStart" aria-label="区间比较起日"/></label><label>本地可知截止（北京时间）<DateField v-model="asOf" :include-time="true" aria-label="本地可知截止"/></label><button @click="page=0;load()">核验并查询</button></div><p>{{indicator(series)}} · {{data.definition?.publisher}} · {{data.definition?.region}} · 原始频率 {{data.definition?.frequency}} · {{unit}}</p><p>{{data.definition?.title}} · 元数据更新时间 {{time(data.definition?.updated_at)}}</p><p>{{page===0?'所选范围最新实际观测':'当前分页最新观测'}} {{rows[0]?.observation_date||'暂无真实观测'}} · {{display(rows[0]?.original_value)}} {{unit}}</p><h3>指标变化分析</h3><article v-for="(c,key) in data.calculations" v-if="rows.length" :key="key"><template v-if="typeof c==='object'"><h4>{{labels[String(key)]}}</h4><p>{{c.status}}</p><p>当前值 {{display(c.current_value)}} · 可比前值 {{display(c.previous_value)}} · 绝对变化 {{display(c.delta)}} {{c.delta_unit||''}} · 相对变化 {{display(c.relative_pct)}}{{c.relative_pct!=null?'%':''}} · 基点 {{display(c.basis_points)}}</p><p>{{c.relative_status}}</p><details><summary>查看计算依据</summary><p>{{c.formula}}</p><p>当前观测ID {{c.current_id}} · 比较观测ID {{c.previous_id||'未取得'}}</p><p>{{c.precision}} · 规则 {{c.rule_version}} · 计算时间 {{time(c.calculated_at)}}</p></details></template></article><p v-if="!rows.length">暂无可比数据</p><figure v-if="actual.length"><figcaption>官方历史曲线 · 单位：{{unit}} · {{actual[0]?.observation_date}} 至 {{actual[actual.length-1]?.observation_date}}（等距观测点）</figcaption><svg viewBox="0 0 800 210" role="img" aria-label="官方真实宏观历史曲线"><polyline :points="points" fill="none" stroke="#4bd4b2" stroke-width="2"/></svg></figure><p>{{data.revision_status}}</p><h3>证据与版本</h3><p>{{data.historical_availability}}</p><article v-for="r in rows" :key="r.evidence_id"><b>{{r.observation_date}} · 原始值 {{display(r.original_value)}} · 本地版本 {{r.local_version_id}}</b><p>{{r.verification_status}} · 哈希{{r.hash_passed?'通过':'未通过'}}</p><p>官方发布 {{time(r.source_published_at,'官方发布时间未知')}} · 首次发现 {{time(r.available_at)}} · 采集 {{time(r.collected_at)}} · 数据入库 {{time(r.ingested_at)}}</p><details><summary>原始证据与定义</summary><p>系列 {{series}} · 证据ID {{r.evidence_id}} · SHA-256 {{r.raw_content_hash}}</p><p>官方历史版本：{{r.official_vintage_id||'尚未取得'}} · {{r.ingestion_kind==='HISTORICAL_BACKFILL'?'历史回填，不实时提醒':'数据更新性质按资格审计确定'}}</p><pre>{{JSON.stringify(r.metadata,null,2)}}</pre></details><a v-if="safeOfficialUrl(r.source_url)" :href="r.source_url" target="_blank" rel="noopener noreferrer">打开原始官方来源</a></article><button :disabled="page===0||busy" @click="page--;load()">上一页</button><button :disabled="!data.has_next||busy" @click="page++;load()">下一页</button><details><summary>历史本地快照（最多100条/页）</summary><p v-for="v in data.versions" :key="v.id">{{v.observation_date}} · {{v.original_value}} · 本地版本 {{v.version}} · {{v.action==='Delete'?'原始响应明确删除':'官方响应动作不等同已证实修订'}} · {{time(v.collected_at)}} · 本地前值 {{v.previous_local_value??'未取得'}} · 本地差异 {{v.local_delta??'暂无可比数据'}} · {{v.response_hash}}</p><p v-if="!data.versions?.length">暂无已保存本地历史版本</p></details><h3>关联事件</h3><p>来源元数据仅证明该指标观测记录关系，不自动确认其对应政策公告。</p><p v-if="!data.events?.length">暂无可核验的宏观指标关联</p><article v-for="e in data.events" :key="e.id"><p>{{e.chinese_title||indicator(series)}} · {{e.observation_date}} · {{time(e.published_at,'官方发布时间未知')}}</p><p>{{e.link_basis}} · 关联核验：原始CSV字段与事件证据ID一致；研究重要性以S64冻结排序为准。</p><a :href="'#/research?event='+e.id">返回原始事件研究详情</a> · <a v-if="transmissionAvailable" :href="'#/linkage?event='+e.id">研究影响传导</a> · <a href="#/important">查看S64重要事件</a></article><h3>来源状态与研究解释</h3><p v-for="s in data.sources" :key="s.id">{{s.name}} · {{s.status==='SUCCESS'?'最近采集成功':s.status==='FAILED'?'最近采集失败':'采集状态待核查'}} · {{s.error_code||'无记录错误'}} · {{time(s.finished_at)}}</p><p>官方事实：原始CSV观测。数学计算：同序列、同单位和同口径十进制变化。</p><p>研究解释：变化仅描述观测数值差异，不能证明原因。影响假设需要真实敞口及其他证据；市场反应尚待验证。未生成AI结论。</p><p>观察基础复用现有关注、事务性Outbox与SSE；重复获取、本地重新计算和历史回填不能冒充实时官方发布。</p></section></template>
<style scoped>.macro-change{min-width:0;font-size:14px}.overview,.filters{display:flex;gap:12px;flex-wrap:wrap}.overview span{padding:12px;background:#132334;border:1px solid #324258;border-radius:6px}.filters label{display:flex;flex-direction:column;gap:6px;max-width:100%}select,input{max-width:100%;min-width:0}select{width:440px}article{padding:14px 0;border-bottom:1px solid #324258}p,pre{overflow-wrap:anywhere}pre{white-space:pre-wrap;font-size:14px}svg{width:100%;background:#101b29}figure{margin:16px 0}h3{margin-top:26px}a{display:inline-block;padding:5px 0}</style>




